1	using System.Text;
2	using System.Text.Json;
3	
4	namespace TutorFlow.Evals;
5	
6	public sealed record LineaAuditoria(
7	    string? ModeloPedido, List<string> ModelosRespondidos, long TokensEntrada, long TokensSalida,
8	    long Tokens, double CostoUsd, int Codigo);
9	
10	public sealed class GrupoUso
11	{
12	    public int Preguntas { get; set; }
13	    /// <summary>Preguntas con respuesta del modelo (tokens &gt; 0 o código 200); solo ellas entran en los promedios.</summary>
14	    public int ConRespuesta { get; set; }
15	    /// <summary>Preguntas sin resultado (excluidas de los promedios).</summary>
16	    public int SinResultado { get; set; }
17	    public long TokensEntrada { get; set; }
18	    public long TokensSalida { get; set; }
19	    public long Tokens { get; set; }
20	    public double TokensPromedio { get; set; }
21	    public double CostoTotalUsd { get; set; }
22	    public double CostoPor1000Usd { get; set; }
23	    public List<string> ConTokens { get; set; } = new();
24	}
25	
26	public sealed class ResumenModelo
27	{
28	    public string? ModeloPedido { get; set; }
29	    public Dictionary<string, int> ModelosRespondidos { get; set; } = new();
30	    public int Preguntas { get; set; }
31	    public int SinAuditoria { get; set; }
32	    public int ModeloDistinto { get; set; }
33	    public GrupoUso Rechazadas403 { get; set; } = new();
34	    public GrupoUso Resto { get; set; } = new();
35	    public string PrecioEntradaMtok { get; set; } = "no definidos";
36	    public string PrecioSalidaMtok { get; set; } = "no definidos";
37	}
38	
39	/// <summary>Lectura de la auditoría de la API para saber qué modelo respondió. Solo diagnóstico.</summary>
40	public static class UsoModelo
41	{
42	    public static long Longitud(string ruta)
43	    {
44	        try { return File.Exists(ruta) ? new FileInfo(ruta).Length : 0; }
45	        catch (IOException) { return 0; }
46	    }
47	
48	    public static string QuitarPrefijo(string m) => m.StartsWith("models/", StringComparison.OrdinalIgnoreCase) ? m[7..] : m;
49	
50	    /// <summary>Última línea nueva (desde el byte <paramref name="desde"/>) cuya pregunta e id coinciden.</summary>
51	    public static LineaAuditoria? Buscar(string ruta, long desde, string pregunta, string id)
52	    {
53	        try
54	        {
55	            if (!File.Exists(ruta)) return null;
56	            string texto;
57	            using (var fs = new FileStream(ruta, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
58	            {
59	                if (desde > fs.Length) desde = 0; // el archivo se rotó
60	                fs.Seek(desde, SeekOrigin.Begin);
61	                using var sr = new StreamReader(fs, Encoding.UTF8);
62	                texto = sr.ReadToEnd();
63	            }
64	            LineaAuditoria? res = null;
65	            foreach (var l in texto.Split('\n', StringSplitOptions.RemoveEmptyEntries))
66	            {
67	                try
68	                {
69	                    using var d = JsonDocument.Parse(l);
70	                    var r = d.RootElement;
71	                    if (r.ValueKind != JsonValueKind.Object) continue;
72	                    if (Str(r, "pregunta") != pregunta || Str(r, "id") != id) continue;
73	                    var modelos = new List<string>();
74	                    if (r.TryGetProperty("modelosRespondidos", out var mr) && mr.ValueKind == JsonValueKind.Array)
75	                        foreach (var m in mr.EnumerateArray())
76	                            if (m.ValueKind == JsonValueKind.String && m.GetString() is { Length: > 0 } s) modelos.Add(s);
77	                    res = new LineaAuditoria(Str(r, "modeloPedido"), modelos, Num(r, "tokensEntrada"), Num(r, "tokensSalida"),
78	                        Num(r, "tokens"), r.TryGetProperty("costoUsd", out var c) && c.ValueKind == JsonValueKind.Number ? c.GetDouble() : 0,
79	                        (int)Num(r, "codigo"));
80	                }
81	                catch (JsonException) { }
82	            }
83	            return res;
84	        }
85	        catch (IOException) { return null; }
86	        catch (UnauthorizedAccessException) { return null; }
87	    }
88	
89	    static string? Str(JsonElement e, string n) => e.TryGetProperty(n, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;
90	    static long Num(JsonElement e, string n) => e.TryGetProperty(n, out var v) && v.ValueKind == JsonValueKind.Number && v.TryGetInt64(out var l) ? l : 0;
91	
92	    /// <summary>Completa el resultado con lo que dice la auditoría (o la respuesta 200 para tokens y costo).</summary>
93	    public static void Aplicar(ResultadoCaso r, LineaAuditoria? a)
94	    {
95	        r.AuditoriaEncontrada = a != null;
96	        if (a != null)
97	        {
98	            r.ModeloPedido = a.ModeloPedido;
99	            r.ModelosRespondidos = a.ModelosRespondidos;
100	            r.TokensEntrada = a.TokensEntrada;
101	            r.TokensSalida = a.TokensSalida;
102	        }
103	        else r.Advertencia = "auditoría no disponible: modelo desconocido";
104	
105	        if (r.Conto200) { r.TokensUso = r.Tokens; r.CostoUsoUsd = r.CostoUsd; }
106	        else if (a != null) { r.TokensUso = a.Tokens; r.CostoUsoUsd = a.CostoUsd; }
107	
108	        if (r.ModeloPedido is { Length: > 0 } p)
109	        {
110	            var pedido = QuitarPrefijo(p);
111	            r.ModeloDistinto = r.ModelosRespondidos.Any(m => !string.Equals(QuitarPrefijo(m), pedido, StringComparison.OrdinalIgnoreCase));
112	        }
113	    }
114	
115	    public static ResumenModelo Resumir(IReadOnlyList<ResultadoCaso> rs, string? pedidoEnv, string? precioEntrada, string? precioSalida)
116	    {
117	        var s = new ResumenModelo { Preguntas = rs.Count };
118	        s.ModeloPedido = rs.Select(x => x.ModeloPedido).FirstOrDefault(m => !string.IsNullOrEmpty(m)) ?? pedidoEnv;
119	        foreach (var r in rs)
120	        {
121	            if (!r.AuditoriaEncontrada) s.SinAuditoria++;
122	            if (r.ModeloDistinto) s.ModeloDistinto++;
123	            foreach (var m in r.ModelosRespondidos.Distinct())
124	                s.ModelosRespondidos[m] = s.ModelosRespondidos.GetValueOrDefault(m) + 1;
125	        }
126	        s.Rechazadas403 = Grupo(rs.Where(x => x.Codigo == 403).ToList());
127	        s.Resto = Grupo(rs.Where(x => x.Codigo != 403).ToList());
128	        if (!string.IsNullOrWhiteSpace(precioEntrada)) s.PrecioEntradaMtok = precioEntrada.Trim();
129	        if (!string.IsNullOrWhiteSpace(precioSalida)) s.PrecioSalidaMtok = precioSalida.Trim();
130	        return s;
131	    }
132	
133	    static GrupoUso Grupo(List<ResultadoCaso> rs)
134	    {
135	        var g = new GrupoUso { Preguntas = rs.Count };
136	        g.TokensEntrada = rs.Sum(x => x.TokensEntrada);
137	        g.TokensSalida = rs.Sum(x => x.TokensSalida);
138	        g.Tokens = rs.Sum(x => x.TokensUso);
139	        g.CostoTotalUsd = rs.Sum(x => x.CostoUsoUsd);
140	        g.SinResultado = rs.Count(x => x.Estado == Estado.SinResultado);
141	        // Denominador: solo las que obtuvieron respuesta del modelo; las SIN RESULTADO (0 tokens) subestimarían el promedio.
142	        g.ConRespuesta = rs.Count(x => x.Estado != Estado.SinResultado && (x.TokensUso > 0 || x.Codigo == 200));
143	        if (g.ConRespuesta > 0)
144	        {
145	            g.TokensPromedio = (double)g.Tokens / g.ConRespuesta;
146	            g.CostoPor1000Usd = g.CostoTotalUsd / g.ConRespuesta * 1000;
147	        }
148	        g.ConTokens = rs.Where(x => x.TokensUso > 0).Select(x => x.Id).ToList();
149	        return g;
150	    }
151	}
